#!/usr/bin/env node
"use strict";

// Builds handbells-used-chart/bundle.js, the one script the options dialog
// imports. A QML import has no require, so every module form.js needs is
// wrapped in a function and resolved by a small loader at the end. The
// bundle is committed, and test/unit/bundle.test.js fails when it is stale.

const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.join(__dirname, "..", "handbells-used-chart");
const ENTRY = "form.js";
const OUTPUT = path.join(ROOT, "bundle.js");

const REQUIRE = /require\("(\.[^"]+)"\)/g;

// Every module the entry reaches, in the order they are first required.
function modules() {
  const found = [];
  const visit = (name) => {
    if (found.includes(name)) return;
    found.push(name);
    const text = fs.readFileSync(path.join(ROOT, name), "utf8");
    for (const [, relative] of text.matchAll(REQUIRE)) {
      visit(path.posix.normalize(path.posix.join(path.posix.dirname(name), relative)));
    }
  };
  visit(ENTRY);
  return found;
}

const LOADER = `
function __resolve(from, name) {
    var parts = from.split("/");
    parts.pop();
    var segments = name.split("/");
    for (var i = 0; i < segments.length; i++) {
        if (segments[i] === "..") parts.pop();
        else if (segments[i] !== ".") parts.push(segments[i]);
    }
    return parts.join("/");
}

function __require(name) {
    if (__cache[name]) return __cache[name].exports;
    var module = { exports: {} };
    __cache[name] = module;
    __modules[name](module, module.exports, function (wanted) {
        return __require(__resolve(name, wanted));
    });
    return module.exports;
}
`;

function generate() {
  const exported = Object.keys(require(path.join(ROOT, ENTRY)));
  let out = "// Generated by tools/bundle.js from form.js and the modules it requires.\n"
    + "// Do not edit it by hand: change those files and run `npm run bundle`.\n\n"
    + "var __modules = {};\nvar __cache = {};\n";
  for (const name of modules()) {
    const body = fs.readFileSync(path.join(ROOT, name), "utf8");
    out += `\n__modules[${JSON.stringify(name)}] = function (module, exports, require) {\n`
      + body + "};\n";
  }
  out += LOADER;
  for (const name of exported) {
    out += `\nfunction ${name}() {\n`
      + `    var entry = __require(${JSON.stringify(ENTRY)});\n`
      + `    return entry.${name}.apply(entry, arguments);\n}\n`;
  }
  return out;
}

if (require.main === module) {
  fs.writeFileSync(OUTPUT, generate());
  process.stdout.write(`Wrote ${path.relative(process.cwd(), OUTPUT)}\n`);
}

module.exports = { generate };
